const cfg = $('Set - Crawl Config').first().json;
const sitemapResp = $input.first().json;

let urls = [];
const xml = sitemapResp.data || sitemapResp.body || (typeof sitemapResp === 'string' ? sitemapResp : '');

if (typeof xml === 'string' && xml.includes('<loc>')) {
  const matches = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)];
  urls = matches.map(m => m[1].trim());
}

if (urls.length === 0) {
  urls = [cfg.seedUrl];
}

if (cfg.sameDomainOnly) {
  let seedHost = '';
  try { seedHost = new URL(cfg.seedUrl).hostname; } catch (e) {}
  urls = urls.filter(u => {
    try { return new URL(u).hostname === seedHost; } catch (e) { return false; }
  });
}

urls = [...new Set(urls)].slice(0, Number(cfg.maxPages) || 50);

return urls.map(u => ({ json: { ...cfg, pageUrl: u } }));

const cfg = $('Loop Over Pages').first().json;
const extracted = $input.first().json;
const pageUrl = cfg.pageUrl;

function toAbsolute(href, base) {
  try { return new URL(href, base).toString(); } catch (e) { return null; }
}

let seedHost = '';
try { seedHost = new URL(cfg.seedUrl).hostname; } catch (e) {}

const hrefs = extracted.linkHrefs || [];
const texts = extracted.linkTexts || [];

const links = hrefs.map((href, i) => {
  const abs = toAbsolute(href, pageUrl);
  if (!abs) return null;
  let isInternal = false;
  try { isInternal = new URL(abs).hostname === seedHost; } catch (e) {}
  return { targetUrl: abs, anchorText: (texts[i] || '').trim().slice(0, 200), isInternal };
}).filter(Boolean);

const bodyText = (extracted.bodyText || '').replace(/\s+/g, ' ').trim();
const wordCount = bodyText ? bodyText.split(' ').length : 0;

return [{
  json: {
    ...cfg,
    title: (extracted.title || '').trim(),
    metaDescription: (extracted.metaDescription || '').trim(),
    h1: Array.isArray(extracted.h1Tags) ? extracted.h1Tags.join(' | ') : (extracted.h1Tags || ''),
    bodyText: bodyText.slice(0, 8000),
    wordCount,
    links,
    crawledAt: new Date().toISOString()
  }
}];

const pageData = $('JS - Normalize Page Data').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let extraction;
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  extraction = JSON.parse(raw);
} catch (e) {
  extraction = { primaryKeywords: [], secondaryKeywords: [], entities: [], topicCategories: [] };
}

return [{
  json: {
    ...pageData,
    primaryKeywords: extraction.primaryKeywords || [],
    secondaryKeywords: extraction.secondaryKeywords || [],
    entities: extraction.entities || [],
    topicCategories: extraction.topicCategories || []
  }
}];

const d = $input.first().json;

const pageRecord = {
  pageUrl: d.pageUrl,
  title: d.title,
  metaDescription: d.metaDescription,
  h1: d.h1,
  wordCount: d.wordCount,
  crawledAt: d.crawledAt
};

const keywordRecords = [
  ...(d.primaryKeywords || []).map(k => ({ pageUrl: d.pageUrl, keyword: (k.keyword || k), keywordType: 'primary', relevanceScore: k.relevanceScore ?? null })),
  ...(d.secondaryKeywords || []).map(k => ({ pageUrl: d.pageUrl, keyword: (k.keyword || k), keywordType: 'secondary', relevanceScore: null }))
];

const entityRecords = (d.entities || []).map(e => ({ pageUrl: d.pageUrl, entityName: e.name, entityType: e.type || 'unknown' }));

const linkRecords = (d.links || []).map(l => ({ sourceUrl: d.pageUrl, targetUrl: l.targetUrl, anchorText: l.anchorText, isInternal: l.isInternal }));

return [{
  json: {
    ...d,
    pageRecord,
    keywordRecords,
    entityRecords,
    linkRecords
  }
}];

