INSERT INTO seo_keywords (keyword, keyword_type)
VALUES ('{{ $json.keyword.replace(/'/g, "''") }}', '{{ $json.keywordType }}')
ON CONFLICT (keyword) DO UPDATE SET keyword_type = EXCLUDED.keyword_type;

INSERT INTO seo_page_keywords (page_url, keyword, relevance_score)
VALUES ('{{ $json.pageUrl.replace(/'/g, "''") }}', '{{ $json.keyword.replace(/'/g, "''") }}', {{ $json.relevanceScore === null || $json.relevanceScore === undefined ? 'NULL' : $json.relevanceScore }})
ON CONFLICT (page_url, keyword) DO UPDATE SET relevance_score = EXCLUDED.relevance_score;

INSERT INTO seo_entities (entity_name, entity_type)
VALUES ('{{ $json.entityName.replace(/'/g, "''") }}', '{{ $json.entityType }}')
ON CONFLICT (entity_name) DO UPDATE SET entity_type = EXCLUDED.entity_type;

INSERT INTO seo_page_entities (page_url, entity_name)
VALUES ('{{ $json.pageUrl.replace(/'/g, "''") }}', '{{ $json.entityName.replace(/'/g, "''") }}')
ON CONFLICT (page_url, entity_name) DO NOTHING;

INSERT INTO seo_page_links (source_url, target_url, anchor_text, is_internal)
VALUES (
  '{{ $json.sourceUrl.replace(/'/g, "''") }}',
  '{{ $json.targetUrl.replace(/'/g, "''") }}',
  '{{ ($json.anchorText || '').replace(/'/g, "''") }}',
  {{ $json.isInternal ? 'true' : 'false' }}
)
ON CONFLICT (source_url, target_url, anchor_text) DO NOTHING;

